507:     const R = mulberry32(0x5eed + region.id.length * 999);
508:     for (let i = 0; i < 1500; i++) {
509:       const x = R() * 192, y = R() * 192, s = 0.4 + R() * 1.8;
510:       const tone = R();
511:       if (region.id === 'mexico') g.fillStyle = tone < 0.5 ? 'rgba(96,64,36,0.20)' : 'rgba(42,24,14,0.30)';
512:       else if (region.id === 'japan') g.fillStyle = tone < 0.5 ? 'rgba(52,82,66,0.18)' : 'rgba(10,22,20,0.28)';
513:       else g.fillStyle = tone < 0.5 ? 'rgba(55,80,52,0.18)' : 'rgba(12,24,17,0.28)';
514:       g.fillRect(x, y, s, s * (1 + R()));
515:     }
516:     if (region.id === 'mexico') {
517:       g.strokeStyle = 'rgba(30,17,10,0.25)';
518:       for (let i = 0; i < 20; i++) {
519:         g.lineWidth = 0.6 + R();
520:         g.beginPath();
521:         let x = R() * 192, y = R() * 192;
522:         g.moveTo(x, y);
523:         for (let k = 0; k < 4; k++) { x += (R() - 0.5) * 30; y += (R() - 0.5) * 30; g.lineTo(x, y); }
