661:   function pathToRgb(hex) {
662:     const h = hex.replace('#', '');
663:     const n = parseInt(h, 16);
664:     return `${(n >> 16) & 255},${(n >> 8) & 255},${n & 255}`;
665:   }
666:   function shadeHex(hex, amt) {
667:     const h = hex.replace('#', '');
668:     const n = parseInt(h, 16);
669:     const r = clamp(Math.round(((n >> 16) & 255) * (1 + amt)), 0, 255);
670:     const g = clamp(Math.round(((n >> 8) & 255) * (1 + amt)), 0, 255);
671:     const b = clamp(Math.round((n & 255) * (1 + amt)), 0, 255);
672:     return `rgb(${r},${g},${b})`;
673:   }
