182:   function teamMembers() { return game.companions.filter((c) => c.state === 'team' && c.hp > 0); }
183:   function residents() { return game.companions.filter((c) => c.state === 'shelter' && c.hp > 0); }
184:   function companionsAt(shelterId) {
185:     return game.companions.filter((c) => c.state === 'shelter' && c.shelterId === shelterId && c.hp > 0);
186:   }
187:   function residentAt(shelterId) { return companionsAt(shelterId)[0] || null; }
188:   function getActiveShelter() { return shelters.find((s) => s.id === game.activeShelter) || null; }
189:   function nearestShelter(x, y, includeCollapsed) {
190:     let best = null;
191:     let bd = Infinity;
192:     for (const s of shelters) {
193:       if (s.state.collapsed && !includeCollapsed) continue;
194:       const d = dist(x, y, s.x, s.y);
195:       if (d < bd) { bd = d; best = s; }
196:     }
197:     return best;
198:   }
