200:   function recruitCompanion(c) {
201:     if (teamMembers().length >= MAX_TEAM) {
202:       toast('TEAM FULL', 'Two is all you can keep alive out here.', 'warn');
203:       Sound.deny();
204:       return;
205:     }
206:     c.state = 'team';
207:     c.hp = Math.min(c.maxHp, c.hp + 8);
208:     c.x = player.x + rand(-24, 24);
209:     c.y = player.y + rand(20, 34);
210:     game.team.push(c.id);
211:     toast('COMPANION JOINED', `${c.name} the ${ROLES[c.role].label} falls in beside you.`, 'good');
212:     banner('A HAND IN THE DARK', c.name.toUpperCase(), 'Two is all you can keep.', '', 2.2);
213:     Sound.recruit();
214:     updateTeamUI(true);
215:   }
216: 
217:   function sendCompanionToShelter(c) {
218:     if (c.state !== 'team') return;
219:     const occupied = new Set(residents().map((r) => r.shelterId));
220:     let candidates = shelters.filter((s) => !s.state.collapsed && !occupied.has(s.id) && s.id !== game.activeShelter);
221:     if (!candidates.length) candidates = shelters.filter((s) => !s.state.collapsed && !occupied.has(s.id));
222:     if (!candidates.length) candidates = shelters.filter((s) => !s.state.collapsed);
223:     if (!candidates.length) {
224:       toast('NO SHELTER LEFT', `${c.name} has nowhere to go.`, 'alert');
225:       return;
226:     }
227:     candidates.sort((a, b) => dist(c.x, c.y, a.x, a.y) - dist(c.x, c.y, b.x, b.y));
228:     const dest = candidates[0];
229:     c.state = 'travel';
230:     c.targetShelterId = dest.id;
231:     c.shelterId = null;
232:     c.hp = Math.max(1, c.hp);
233:     game.team = game.team.filter((id) => id !== c.id);
234:     toast('SENT AHEAD', `${c.name} will hold ${dest.name} until you call.`, '');
235:     Sound.ui();
236:     updateTeamUI(true);
237:   }
238: 
239:   function recallCompanion(c) {
240:     if (teamMembers().length >= MAX_TEAM) {
241:       toast('TEAM FULL', 'Send someone away first.', 'warn');
242:       Sound.deny();
243:       return;
244:     }
245:     c.state = 'team';
246:     c.shelterId = null;
247:     c.targetShelterId = null;
248:     c.x = player.x + rand(-26, 26);
249:     c.y = player.y + rand(22, 38);
250:     game.team.push(c.id);
251:     toast('AT YOUR SIDE', `${c.name} rejoins you.`, 'good');
252:     Sound.recruit();
253:     updateTeamUI(true);
254:   }
