256:   function damageCompanion(c, amount) {
257:     if (c.hp <= 0 || (c.invuln || 0) > 0) return;
258:     c.invuln = 0.38;
259:     c.hp = Math.max(0, c.hp - amount);
260:     c.hitFlash = 0.18;
261:     if (c.hp <= 0) {
262:       c.state = 'dead';
263:       c.shelterId = null;
264:       game.team = game.team.filter((id) => id !== c.id);
265:       spawnMist(c.x, c.y, 18, '#b6a4a0');
266:       toast('COMPANION LOST', `${c.name} the ${ROLES[c.role].label} is gone.`, 'alert');
267:       Sound.kill();
268:       updateTeamUI(true);
269:     }
270:   }
