655:     game.phaseTime = 0;
656:     game.nightDuration = Math.round(NIGHT_BASE + Math.min(28, (game.day - 1) * 3.4) + (game.chapter - 1) * 5);
657:     game.phaseDuration = game.day >= CHAPTER_NIGHTS ? 150 : game.nightDuration;
658:     game.nightKills = 0;
659:     game.spawnTimer = 2.2;
660:     game.queueTimer = 0.1;
661:     const active = getActiveShelter();
662:     if (active) active.state.breached = active.state.integrity <= 0;
663:     const haunt = active ? active.state.haunt : 0;
664:     game.spawnQueue = Math.round((5 + game.day * 2.2 + haunt * 2 + (game.chapter - 1) * 3) * 1.08);
665:     game.trickle = Math.max(1.25, 4.6 - game.day * 0.24 - haunt * 0.34 - (game.chapter - 1) * 0.2);
666:     spawnResidentRaids();
667: 
668:     if (game.day >= CHAPTER_NIGHTS) {
669:       game.bossFight = true;
670:       spawnBoss();
671:       banner('NIGHT SEVEN', 'SCP-682 HAS BREACHED', 'Nothing ends until it does.', 'boss', 4.2);
672:       toast('EXTREME THREAT', 'SCP-682 is awake. Kill it to finish the chapter.', 'alert');
673:       Sound.bossRoar();
674:     } else {
675:       banner('NIGHTFALL', 'THEY ARE COMING', active ? `Hold ${active.name} until dawn.` : 'You have no shelter. Keep moving.', 'night', 3.2);
676:       if (!active) toast('NO SHELTER', 'They will come for you directly. Run. Shoot. Survive.', 'alert');
677:       else if (haunt >= 2) toast('REMEMBERED GROUND', `${active.name} knows your scent. They are already close.`, 'alert');
678:       Sound.night();
679:     }
